INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'6ba7b810-9dad-11d1-80b4-00c04fd430c8', N'الأوراق: البطاقة القديمة (حتى لو منتهية)، وصورة شخصية حديثة خلفية بيضاء، ورسوم 50 جنيه. لو البطاقة قديمة جداً أو تالفة، هتحتاج تقديم إقرار فقدان وتدفع غرامة صغيرة حوالي 20 جنيهاً. (الموقع: القاهرة)', N'7c9e6679-7425-40de-944b-e07fc1f90ae7', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 8, 0, 0, 16, CAST(N'2026-03-10T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'f6a7b8c9-d0e1-2345-6789-0abcdef12345', N'القيد الفردي: بيبين حالة الشخص لوحده (اسمه، تاريخ ميلاده، مهنته، حالته الاجتماعية). القيد العائلي: بيبين رب الأسرة والزوجة والأبناء اللي لسه تحت السن (أقل من 18 سنة). القيد العائلي بيستخدم عشان تسجيل الأطفال في المدارس أو استخراج جوازات السفر للأسرة. (الموقع: الجيزة)', N'e5f6a7b8-c9d0-1234-5678-90abcdef1234', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 21, 0, 0, 42, CAST(N'2026-03-08T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'c1d2e3f4-a5b6-7c8d-9e0f-1a2b3c4d5e6f', N'روح أقرب سجل مدني، قدم إقرار فقدان (بتكتب إن البطاقة ضاعت أو اترددت أو اتحرقت)، وادفع رسوم 50 جنيه + غرامة 20 جنيه. لازم تقدم إيصال مرافق أو عقد إيجار لإثبات العنوان عشان البطاقة الجديدة تطلع بنفس البيانات أو بالعنوان الجديد. (الموقع: القاهرة)', N'b0c1d2e3-f4a5-6b7c-8d9e-0f1a2b3c4d5e', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 6, 0, 0, 12, CAST(N'2026-03-17T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'e1f2a3b4-c5d6-7e8f-9a0b-1c2d3e4f5a6b', N'أيوة، بس لازم تقدم مستند رسمي يثبت المهنة الجديدة. لو موظف: خطاب من جهة العمل مختوم بختم النسر. لو صاحب مهنة حرة: كارنيه النقابة أو شهادة مزاولة المهنة. لو عاطل: هتثبت ''عاطل'' أو ''رب منزل'' بدون مستندات. (الموقع: الجيزة)', N'd0e1f2a3-b4c5-6789-0123-def123456789', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 7, 0, 0, 14, CAST(N'2026-03-08T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'a1b2c3d4-e5f6-7a8b-9c0d-1e2f3a4b5c6d', N'لو الست بتغير الحالة الاجتماعية من أعزب لمتزوج، مش لازم الزوج يحضر، هي بتقدم عقد الزواج بس. لو الزوج عايز يغير حالته لـ ''متزوج''، لازم هو يحضر شخصياً أو يقدم توكيل. لو الحالة ''مطلق'' أو ''أرمل''، الشخص نفسه بس اللي بيحضر مع الوثيقة المطلوبة. (الموقع: الإسكندرية)', N'f0a1b2c3-d4e5-6789-0123-f45678901234', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 4, 0, 0, 8, CAST(N'2026-03-11T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'b1c2d3e4-f5a6-7b8c-9d0e-1f2a3b4c5d6e', N'للأسف، لازم يكون عندك عنوان ثابت وموثق. هتحتاج تقديم عقد إيجار موثق أو إيصال مرافق (كهرباء أو غاز) باسمك أو اسم رب الأسرة. غير كده، هيرفضوا استخراج البطاقة أو تجديدها. (الموقع: الجيزة)', N'a3bb4e5b-9d4b-4a3e-8d5f-3b2c1a6e9d8c', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 15, 0, 0, 30, CAST(N'2026-03-05T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
