INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'a3b4c5d6-e7f8-9a0b-1c2d-3e4f5a6b7c8d', N'لو شغال حر (مثلاً: كهربائي، سباك، مصور)، روح الوحدة المحلية أو الحي التابع له وقدم إقرار مزاولة مهنة. ممكن تطلع كارنيه مزاولة مهنة من الغرفة التجارية أو اتحاد الصناعات حسب نشاطك. من غير المستندات دي، مش هيعترفوا بمهنتك. (الموقع: القاهرة)', N'f2a3b4c5-d6e7-8f9a-0b1c-2d3e4f5a6b7c', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 9, 0, 0, 18, CAST(N'2026-03-22T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
