INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'c5d6e7f8-a9b0-1c2d-3e4f-5a6b7c8d9e0f', N'أيوة، لازم عقد إيجار موثق من الشهر العقاري. أو ممكن تقدم إيصال مرافق (كهرباء أو غاز) حديث باسمك أو اسم رب الأسرة (مع إثبات صلة القرابة زي بطاقة العائلة أو شهادة ميلاد). الفواتير الإلكترونية أو صورها مقبولة. (الموقع: الإسكندرية)', N'b4c5d6e7-f8a9-0b1c-2d3e-4f5a6b7c8d9e', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 14, 0, 0, 28, CAST(N'2026-03-01T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
