INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'e5f6a7b8-c9d0-1e2f-3a4b-5c6d7e8f9a0b', N'الخدمة العادية: 15 يوم عمل. الخدمة المستعجلة: 3 أيام وبتكلف حوالي 150 جنيه بدل 50 جنيه. في مكاتب معينة في المولات بتطلعها في نفس اليوم لكن برسوم أعلى (250-300 جنيه). (الموقع: القاهرة)', N'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 20, 0, 0, 40, CAST(N'2026-03-12T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
