INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'a5b6c7d8-e9f0-1a2b-3c4d-5e6f7a8b9c0d', N'أحسن وقت تروح: أيام الأحد للثلاثاء من الساعة 8 الصبح لـ 10 الصبح. تجنب يوم الأربعاء (زحمة معاملات) والخميس (نص دوام). كمان تجنب أول وأخر أسبوع في الشهر عشان الموظفين والمواطنين بيخلصوا معاملات. مولات الخدمة أفضل من حيث الزحمة. (الموقع: القاهرة)', N'f4a5b6c7-d8e9-0f1a-2b3c-4d5e6f7a8b9c', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 22, 0, 0, 44, CAST(N'2026-03-19T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
