INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'b2c3d4e5-f6a7-8901-2345-67890abcdef1', N'روح مكتب السجل المدني التابع لمحل إقامتك. هتحتاج أصل بطاقة الرقم القومي لرب الأسرة (الأب أو الأم)، وشهادة ميلاد الأبناء (اللي لسه تحت السن)، ورسوم 10 جنيهات. بيطلع فوري أو في نفس اليوم. بيستخدم كإثبات للعلاقات العائلية في المدارس أو المستشفيات. (الموقع: القاهرة)', N'a1b2c3d4-e5f6-7890-1234-567890abcdef', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 9, 0, 0, 18, CAST(N'2026-03-02T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'c7d8e9f0-a1b2-3c4d-5e6f-7a8b9c0d1e2f', N'للأسف، مكتب العباسية (مكتب القاهرة الكبرى) معروف بزحمة خانقة طول اليوم. لو مضطر تروحله، روح من 7 الصبح بالضبط أو استنى للعصر بعد الساعة 2. الأفضل تروح لأي مكتب تابع لحيك في مدينتك زي مدينة نصر أو مصر الجديدة أو المعادي هتخلص أسرع بكتير. (الموقع: القاهرة)', N'b6c7d8e9-f0a1-2345-6789-0abcdef12345', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 30, 0, 0, 60, CAST(N'2026-03-23T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'e7f8a9b0-c1d2-3e4f-5a6b-7c8d9e0f1a2b', N'الرسوم الرسمية: 50 جنيهاً للاستخراج العادي (15 يوم). الخدمة المستعجلة: 150 جنيهاً (3 أيام). لو بدل فاقد أو تالف: 50 جنيهاً + غرامة 20 جنيهاً لو قدمت إقرار فقدان. رسوم التوصيل للبيت: 30 جنيهاً إضافية. (الموقع: القاهرة)', N'd6e7f8a9-b0c1-2d3e-4f5a-6b7c8d9e0f1a', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 25, 0, 0, 50, CAST(N'2026-03-14T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'a7b8c9d0-e1f2-3a4b-5c6d-7e8f9a0b1c2d', N'أيوة، في خدمة الاستعجال بـ 150 جنيه بدل 50 جنيه، بتستلمها خلال 3 أيام عمل. فيه كمان خدمة ''استلام فوري'' في بعض مراكز الخدمة في المولات التجارية الكبيرة (زي City Stars أو Mall of Arabia) لكن برسوم أعلى تصل لـ 300 جنيه. (الموقع: الإسكندرية)', N'f6a7b8c9-d0e1-2f3a-4b5c-6d7e8f9a0b1c', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 5, 0, 0, 10, CAST(N'2026-03-18T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'd4e5f6a7-b8c9-0123-4567-890abcdef123', N'في أغلب المكاتب بيطلع في نفس اليوم خلال ساعة أو ساعتين. لو المكتب زحمة، ممكن ياخد من يوم ليومين. لو طلبه من مكتب غير تابع لمحل إقامتك (مثلاً قاطن في القاهرة وعايز قيد من محافظة أسيوط)، هتستنى 3-5 أيام عشان ييجي من المحافظة التانية. (الموقع: الإسكندرية)', N'c3d4e5f6-a7b8-9012-3456-7890abcdef12', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 14, 0, 0, 28, CAST(N'2026-03-05T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'a9b0c1d2-e3f4-5a6b-7c8d-9e0f1a2b3c4d', N'أيوة، لو البطاقة منتهية من أكثر من 6 شهور، هتدفع غرامة 20 جنيهاً عن كل سنة تأخير (بحد أقصى 100 جنيه). لو منتهية من أقل من 6 شهور، بتجدد عادي بدون غرامة. الأفضل متأخرش عشان تتعرض للمساءلة لو موظف حكومي طلبها منك. (الموقع: الجيزة)', N'f8a9b0c1-d2e3-4f5a-6b7c-8d9e0f1a2b3c', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 11, 0, 0, 22, CAST(N'2026-03-09T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'a9b0c1d2-e3f4-5678-9012-abcdef123789', N'أسهل طريقة: من خلال تطبيق ''مرورك'' أو موقع ''البوابة المصرية الموحدة''. بتدخل رقم العربية أو رقم رخصة القيادة، بتظهر كل المخالفات المسجلة عليك. كمان تقدر تتصل بالرقم 01221110000 (خدمة عملاء المرور). أو تروح بنفسك لأي إدارة مرور وتطلب ''شهادة مخالفات''. لازم تتأكد قبل ما تجدد الرخصة عشان أي مخالفة هتمنع التجديد. (الموقع: القاهرة)', N'f8a9b0c1-d2e3-4567-8901-f78901234567', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 35, 0, 0, 70, CAST(N'2026-04-23T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'b8c9d0e1-f2a3-4567-8901-bcdef1234567', N'أيوة، تقدر تطلبه من خلال بوابة ''مصر الرقمية'' (digital.egypt.gov.eg). بتسجل دخولك، وتختار ''قيد عائلي''، وتدفع الرسوم أونلاين (10 جنيهات)، وتستلمه على بريدك الإلكتروني كملف PDF مختوم إلكترونياً. بيطلع فوري وممكن تطبعه في البيت. (الموقع: القاهرة)', N'a7b8c9d0-e1f2-3456-7890-abcdef123456', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 27, 0, 0, 54, CAST(N'2026-03-10T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'c9d0e1f2-a3b4-5678-9012-cdef12345678', N'السجل المدني: تابع للحكومة، رسومه أقل، بس زحمة كتير وخدمة أبطأ. المولات: مراكز خدمة خاصة متعاقدة مع الحكومة، بتقدم خدمة أسرع (نفس اليوم أو اليومين) وفي أماكن مكيفة وانتظار أقل، لكن الرسوم أغلى بكتير (ضعف أو تلاتة أضعاف). (الموقع: القاهرة)', N'b8c9d0e1-f2a3-4567-8901-bcdef1234567', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 10, 0, 0, 20, CAST(N'2026-03-20T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'd8e9f0a1-b2c3-4567-8901-def456789012', N'روح المدرسة اللي درست فيها آخر سنة. بتطلب بيان نجاح (أو شهادة مؤقتة) من شؤون الطلاب. هتحتاج بطاقة الرقم القومي (بتاعتك أو بتاعت ولي الأمر لو لسه تحت 18). الرسوم: 20 جنيه. بيطلع في نفس اليوم. لو المدرسة اتهدت أو اتغير اسمها، روح الإدارة التعليمية التابعة لها. لو عايز بيان نجاح للجامعة أو السفر، ممكن تطلبه أونلاين من موقع ''التنسيق الإلكتروني'' التابع لوزارة التعليم العالي. (الموقع: الإسكندرية)', N'c7d8e9f0-a1b2-3456-7890-cdef45678901', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 9, 0, 0, 18, CAST(N'2026-05-03T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'e3f4a5b6-c7d8-9012-3456-ef1237890123', N'أيوة، لازم تروح بنفسك عشان البصمة والصورة الشخصية والكشف البصري. مينفعش حد يعملك توكيل لاستخراج بطاقة رقم قومي لأول مرة أو التجديد، لأنها وثيقة هوية بيومترية. الاستلام ممكن أي حد بالبطاقة القديمة والإيصال. (الموقع: الإسكندرية)', N'd2e3f4a5-b6c7-8d9e-0f1a-2b3c4d5e6f7a', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 18, 0, 0, 36, CAST(N'2026-03-21T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'e9f0a1b2-c3d4-5678-9012-ef4567890123', N'لازم تقدم مستند يثبت التغيير: لو اتجوزت: وثيقة الزواج الأصلية (عقد الزواج). لو اتطلقت: وثيقة الطلاق النهائية. لو اتوفى الزوج/الزوجة: شهادة الوفاة. بتروح السجل المدني وتطلب تعديل الحالة الاجتماعية وبتدفع 50 جنيه رسوم بطاقة جديدة بالحالة المحدثة. (الموقع: الجيزة)', N'd8e9f0a1-b2c3-4d5e-6f7a-8b9c0d1e2f3a', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 13, 0, 0, 26, CAST(N'2026-03-07T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
INSERT [dbo].[Answers] ([Id], [Content], [QuestionId], [UserId], [IsAccepted], [UpVotes], [DownVotes], [SuccessCount], [Score], [CreatedAt], [UpdatedAt], [IsDeleted], [DeletedAt]) VALUES (N'f0a1b2c3-d4e5-6789-0123-f45678901234', N'أول حاجة تقدم في مدرسة تعليم القيادة المرخصة من المرور. بتاخد 12 درس نظري و12 درس عملي. بعد كده بتقدم لموعد الاختبار في إدارة المرور التابع لمحل إقامتك. الاختبار فيه جزء نظري (إشارات وقوانين) وجزء عملي (قيادة). بعد النجاح، بتدفع رسوم الرخصة: 250 جنيه (لسنة) أو 500 جنيه (لـ 10 سنين). هتحتاج: بطاقة رقم قومي، 6 صور شخصية، شهادة صحية من مستشفى حكومي، شهادة اجتياز من مدرسة القيادة. (الموقع: الجيزة)', N'e9f0a1b2-c3d4-5678-9012-ef4567890123', N'9a58d7d1-87c7-42c8-00de-08de97263e92', 0, 24, 0, 0, 48, CAST(N'2026-04-05T00:00:00.0000000' AS DateTime2), NULL, 0, NULL)
GO
